def ev(b):
 o=b.outcome(claim_draw=True)
 if o: return 0 if o.winner is None else (100000 if o.winner==b.turn else -100000)
 s=0
 for sq,p in b.piece_map().items():
  x=V[p.piece_type]+(PS.get(p.piece_type,[0]*64)[sq if p.color else chess.square_mirror(sq)])
  s += x if p.color==b.turn else -x
 return s

def q(b,a,beta,ply=0):
 global nodes; nodes+=1
 stand=ev(b)
 if stand>=beta:return beta
 if stand>a:a=stand
 moves=[m for m in b.legal_moves if b.is_capture(m) or m.promotion or b.gives_check(m)]
 moves.sort(key=lambda m:(10000 if b.gives_check(m) else 0)+(10*V.get(b.piece_type_at(m.to_square),0)-V.get(b.piece_type_at(m.from_square),0) if b.is_capture(m) else 0),reverse=True)
 for m in moves[:20]:
  b.push(m);v=-q(b,-beta,-a,ply+1) if ply<8 else -ev(b);b.pop()
  if v>=beta:return beta
  if v>a:a=v
 return a

def neg(b,d,a,beta):
 global nodes;nodes+=1
 if time.time()>end: raise TimeoutError
 if d<=0:return q(b,a,beta)
 moves=list(b.legal_moves)
 if not moves:return ev(b)
 def score(m):
  return (20000 if b.gives_check(m) else 0)+(10*V.get(b.piece_type_at(m.to_square),0)-V.get(b.piece_type_at(m.from_square),0) if b.is_capture(m) else 0)+(1000 if m.promotion else 0)
 moves.sort(key=score,reverse=True)
 for m in moves:
  b.push(m);v=-neg(b,d-1,-beta,-a);b.pop()
  if v>=beta:return beta
  if v>a:a=v
 return a
